-- Feature 24 local fixture metadata only.  No package bytes, values, URLs, or credentials.
CREATE TABLE IF NOT EXISTS portability_scopes(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_policies(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_synthetic_auth(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_feature03_contexts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_requests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,request_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,request_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_domain_plans(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_cutoffs(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_source_record_refs(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_field_decisions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_omissions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_domain_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_file_descriptors(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_manifests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_assembly_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_verification_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_grants(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_delivery_attempts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,sequence integer NOT NULL CHECK(sequence>0),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),UNIQUE(operator_test_id,scope_hash,sequence),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_delivery_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_cleanup_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,CHECK((payload->>'state')<>'cleared' OR (payload->>'residual_file_count')='0'),PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_root_manifests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_state_snapshots(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_test_center_bundles(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES portability_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS portability_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS portability_conflicts(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE OR REPLACE FUNCTION portability_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'portability_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['portability_scopes','portability_policies','portability_synthetic_auth','portability_feature03_contexts','portability_requests','portability_domain_plans','portability_cutoffs','portability_source_record_refs','portability_field_decisions','portability_omissions','portability_domain_receipts','portability_file_descriptors','portability_manifests','portability_assembly_receipts','portability_verification_receipts','portability_grants','portability_delivery_attempts','portability_delivery_receipts','portability_cleanup_receipts','portability_root_manifests','portability_state_snapshots','portability_test_center_bundles','portability_request_claims','portability_conflicts'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS portability_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER portability_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION portability_append_only()',t); END LOOP; END $$;
